/* 索引→dBm: 0..14 线性 (level-8)*3, level 15 例外 = +20 (与固件一致) */
function blePwrDbm(lv){
    return (lv < 0) ? -99 : (lv === 15 ? 20 : (lv - 8) * 3);
}
