const RF_PAGES = RF_NAV.flatMap(g => g.items);
const RF_BY_KEY = Object.fromEntries(RF_PAGES.map(p => [p.k, p]));
let rfCur = null;

function rfOpen(key){
    const page = RF_BY_KEY[key] || RF_BY_KEY[RF_PAGES.find(p => p.panel === key)?.k] || RF_PAGES[0];
    if (!page) return;
    const pan = document.getElementById('pan-' + page.panel);
    if (!pan) return;

    const tab = document.querySelector('.tab[data-tab="' + page.panel + '"]');
    if (tab) tab.click();

    document.querySelectorAll('.panel').forEach(x => x.classList.remove('paged'));
    pan.classList.add('paged');
    const blks = Array.from(pan.children).filter(el => el.classList.contains('blk'));
    blks.forEach((b, i) => b.classList.toggle('on', page.blks.includes(i)));

    rfCur = page.k;
    const tip = document.getElementById('pgTip');
    if (tip){
        tip.textContent = page.tip || '';
        tip.style.display = page.tip ? '' : 'none';
    }
    document.querySelectorAll('#menuList .mi').forEach(mi =>
        mi.classList.toggle('active', mi.dataset.page === page.k));

    const stage = document.getElementById('stage');
    if (stage) stage.scrollTop = 0;
    document.getElementById('menu')?.classList.remove('open');
    document.getElementById('menuBtn')?.setAttribute('aria-expanded', 'false');
    if (navigator.vibrate){ try { navigator.vibrate(3); } catch(_){} }
}

function rfRenderMenu(){
    const box = document.getElementById('menuList');
    if (!box) return;
    box.innerHTML = RF_NAV.map(g =>
        '<div class="mgroup">' + g.g + '</div>' +
        g.items.map(it =>
            '<button type="button" class="mi" data-page="' + it.k + '" data-k="' +
            (g.g + ' ' + it.lb + ' ' + it.d).toLowerCase() + '">' +
            '<span class="ic"></span><span class="lb">' + it.lb + '<i>' + it.d + '</i></span>' +
            '</button>'
        ).join('')
    ).join('');
    box.querySelectorAll('.mi').forEach(mi =>
        mi.addEventListener('click', () => rfOpen(mi.dataset.page)));
}

/* 候选列表: 有数据就能点选, 不用背 BSSID */
function rfRefreshPicks(){
    const ap = apList || [];
    const sta = clientList || [];
    const mk = (arr, fn) => arr.map(fn).join('');
    const byRssi = [...ap].sort((a, b) => b.rssi - a.rssi);

    const dlAp = document.getElementById('dlAp');
    if (dlAp) dlAp.innerHTML = mk(byRssi, a =>
        `<option value="${a.bssid}">${a.ssid} · CH${a.channel} · ${a.rssi}dBm</option>`);

    const dlSsid = document.getElementById('dlSsid');
    if (dlSsid) dlSsid.innerHTML = mk(
        [...new Set(byRssi.map(a => a.ssid).filter(x => x && x !== '(hidden)'))],
        x => `<option value="${x}"></option>`);

    const dlSta = document.getElementById('dlSta');
    if (dlSta) dlSta.innerHTML = mk(sta, c =>
        `<option value="${c.mac}">${devLabel(c.mac, c.vendor)} · ${c.rssi}dBm</option>`);

    const dlMac = document.getElementById('dlMac');
    if (dlMac) dlMac.innerHTML =
        mk(byRssi, a => `<option value="${a.bssid}">${a.ssid} (AP)</option>`) +
        mk(sta, c => `<option value="${c.mac}">${devLabel(c.mac, c.vendor)} (客户端)</option>`);

    if (typeof renderFtmApSelect === 'function') renderFtmApSelect();
}

function rfSyncTarget(){
    const bar = document.getElementById('tgtBar');
    const name = document.getElementById('tgtName');
    const meta = document.getElementById('tgtMeta');
    if (!bar || !name || !meta) return;
    const ap = selectedAp;
    const cli = selectedClient;
    if (ap){
        bar.classList.remove('empty');
        name.textContent = ap.ssid || '(隐藏)';
        meta.textContent = [ap.bssid, 'CH' + ap.channel, ap.rssi + 'dBm',
                            devLabel(ap.bssid, ap.vendor), ap.pmf ? 'PMF' : '']
            .filter(Boolean).join(' · ');
        document.getElementById('tgtScan').textContent = '扫描';
        document.getElementById('tgtChange').textContent = '更换';
    } else if (cli){
        bar.classList.remove('empty');
        name.textContent = '客户端 ' + cli.mac.slice(-8);
        meta.textContent = devLabel(cli.mac, cli.vendor) + ' · ' + cli.rssi + 'dBm';
        document.getElementById('tgtScan').textContent = '扫描';
        document.getElementById('tgtChange').textContent = '更换';
    } else {
        bar.classList.add('empty');
        name.textContent = '未选择';
        meta.textContent = '';
        document.getElementById('tgtScan').textContent = '扫描附近热点';
    }
}

window.RFNav = { open: rfOpen, pages: RF_PAGES, current: () => rfCur };
window.RFRefreshPicks = rfRefreshPicks;
window.RFSyncTarget = rfSyncTarget;

/* 旧入口 gotoTab 仍可能被调用(快捷按钮/扫描完成), 统一走分页 */
window.gotoTab = function(name){ rfOpen(name); };

(function(){
    rfRenderMenu();
    document.getElementById('tgtScan')?.addEventListener('click', () => {
        rfOpen('scan');
        document.getElementById('btnScanApFast')?.click();
    });
    document.getElementById('tgtChange')?.addEventListener('click', () => rfOpen('scan'));
    rfOpen('dash');
    rfSyncTarget();
    rfRefreshPicks();
    renderCliRef('');
})();

/*
   图表页 — 手绘 Canvas, 不引第三方库
   只读 apList, 不发命令, 不在连接路径上
 */
(function(){
    const pan = document.getElementById('pan-chart');
    if (!pan) return;

    const P = id => document.getElementById(id);
    const INK = 'rgba(232,241,255,';
    const ACC = '#eaf2ff';
    const ERR = '#ff6b4a';
    const FONT = '9px ui-monospace,SFMono-Regular,Menlo,monospace';

    const cv = {
        chan: P('chChan'), rssi: P('chRssi'), enc: P('chEnc'),
        vend: P('chVend'), time: P('chTime'),
    };
    if (Object.values(cv).some(c => !c)) return;

    function fit(c){
        const w = c.clientWidth || 300, h = c.clientHeight || 112;
        const dpr = Math.min(window.devicePixelRatio || 1, 2);
        if (c.width !== Math.round(w*dpr) || c.height !== Math.round(h*dpr)){
            c.width = Math.round(w*dpr); c.height = Math.round(h*dpr);
        }
        const ctx = c.getContext('2d');
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        ctx.clearRect(0, 0, w, h);
        ctx.font = FONT;
        ctx.textBaseline = 'middle';
        ctx.textAlign = 'left';
        return { ctx, w, h };
    }

    function empty(ctx, h, text){
        ctx.fillStyle = INK + '.22)';
        ctx.textAlign = 'left';
        ctx.fillText(text, 2, h / 2);
    }

    function bar(ctx, x, y, w, h, r){
        if (h < 1 || w < .6) return;
        const rr = Math.min(r, w / 2, h);
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(x, y, w, h, [rr, rr, 0, 0]);
        else ctx.rect(x, y, w, h);
        ctx.fill();
    }

    /* 平滑: 每个数向目标靠 22%, 变化小到看不见就贴齐, 免得一直重绘 */
    function lerpMap(disp, target){
        for (const [k, v] of target){
            const c = disp.get(k) || 0;
            disp.set(k, Math.abs(v - c) < .02 ? v : c + (v - c) * .22);
        }
        for (const k of [...disp.keys()]) if (!target.has(k)) disp.delete(k);
    }
    function lerpArr(disp, target){
        for (let i = 0; i < disp.length; i++)
            disp[i] = Math.abs(target[i] - disp[i]) < .02 ? target[i] : disp[i] + (target[i] - disp[i]) * .22;
    }

    const dispChan = new Map(), dispVend = new Map();
    const dispRssi = new Array(14).fill(0), dispEnc = new Map();

    /* ---- 信道占用 ---- */
    function drawChan(){
        const { ctx, w, h } = fit(cv.chan);
        const target = new Map();
        for (const a of apList) if (a.channel) target.set(a.channel, (target.get(a.channel) || 0) + 1);
        if (!target.size) return empty(ctx, h, '暂无 AP · 扫描后显示信道占用');
        lerpMap(dispChan, target);

        const chs = [...dispChan.keys()].sort((a, b) => a - b);
        const vals = chs.map(c => dispChan.get(c));
        const max = Math.max(1, ...vals);
        const gap = chs.length > 22 ? 1 : 3;
        const bw = Math.max(2, (w - gap * (chs.length - 1)) / chs.length);
        const base = h - 13, top = 14;

        ctx.strokeStyle = INK + '.08)';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(0, base + .5); ctx.lineTo(w, base + .5); ctx.stroke();

        /* 2.4G 与 5G 的分界: 78 条信道铺开时一眼能看出两段 */
        const cut = chs.findIndex(c => c >= 36);
        if (cut > 0){
            const x = cut * (bw + gap) - gap / 2;
            ctx.save();
            ctx.setLineDash([2, 3]);
            ctx.strokeStyle = INK + '.16)';
            ctx.beginPath(); ctx.moveTo(x, 6); ctx.lineTo(x, base); ctx.stroke();
            ctx.restore();
        }

        let busyI = 0;
        vals.forEach((v, i) => { if (v > vals[busyI]) busyI = i; });

        chs.forEach((ch, i) => {
            const v = vals[i];
            const bh = (v / max) * (base - top);
            const x = i * (bw + gap);
            ctx.fillStyle = i === busyI ? ACC : INK + (0.2 + 0.5 * (v / max)).toFixed(2) + ')';
            bar(ctx, x, base - bh, bw - (gap > 1 ? 0 : 0), bh, 2);
            if (bw >= 11 || i % 4 === 0){
                ctx.fillStyle = INK + (i === busyI ? '.75)' : '.3)');
                ctx.textAlign = 'center';
                ctx.fillText(String(ch), x + bw / 2, h - 5);
                ctx.textAlign = 'left';
            }
        });
        ctx.fillStyle = INK + '.55)';
        ctx.fillText('最忙 ch' + chs[busyI] + ' ×' + Math.round(vals[busyI]), 2, 7);
    }

    /* ---- 信号强度 ---- */
    function drawRssi(){
        const { ctx, w, h } = fit(cv.rssi);
        if (!apList.length) return empty(ctx, h, '暂无 AP');
        const t = new Array(14).fill(0);
        for (const a of apList){
            if (typeof a.rssi !== 'number' || !a.rssi) continue;
            const i = Math.max(0, Math.min(13, Math.floor((a.rssi + 95) / 5)));
            t[i]++;
        }
        lerpArr(dispRssi, t);
        const max = Math.max(1, ...dispRssi);
        const gap = 3, bw = (w - gap * 13) / 14, base = h - 14;

        for (let i = 0; i < 14; i++){
            const v = dispRssi[i], bh = (v / max) * (base - 12);
            ctx.fillStyle = INK + (0.18 + 0.55 * (i / 13)).toFixed(2) + ')';
            bar(ctx, i * (bw + gap), base - bh, bw, bh, 2);
        }
        ctx.strokeStyle = INK + '.08)';
        ctx.beginPath(); ctx.moveTo(0, base + .5); ctx.lineTo(w, base + .5); ctx.stroke();

        ctx.fillStyle = INK + '.3)';
        ctx.fillText('-95', 2, h - 5);
        ctx.textAlign = 'right';
        ctx.fillText('-25 dBm', w - 6, h - 5);
        ctx.textAlign = 'left';
    }

    /* ---- 加密构成 ---- */
    const ENC_CATS = ['开放', 'WEP', 'WPA 混合', 'WPA2', 'WPA3', '未知'];
    const ENC_COLS = [ERR, 'rgba(255,107,74,.48)', INK + '.24)', INK + '.44)', ACC, INK + '.12)'];

    function encCat(e){
        const s = (e || '').toUpperCase();
        if (!s || s === 'OPEN') return '开放';
        if (s === 'WEP') return 'WEP';
        if (s === 'WPA3') return 'WPA3';
        if (s === 'WPA2') return 'WPA2';
        if (s.indexOf('WPA') === 0) return 'WPA 混合';
        return '未知';
    }

    function drawEnc(){
        const { ctx, w, h } = fit(cv.enc);
        const target = new Map();
        for (const a of apList){
            const k = encCat(a.enc);
            target.set(k, (target.get(k) || 0) + 1);
        }
        if (!target.size) return empty(ctx, h, '暂无 AP');
        lerpMap(dispEnc, target);

        const total = [...dispEnc.values()].reduce((s, v) => s + v, 0) || 1;
        const cx = 50, cy = h / 2, r = Math.min(44, h / 2 - 8), th = 13;

        let a0 = -Math.PI / 2;
        ENC_CATS.forEach((c, i) => {
            const v = dispEnc.get(c) || 0;
            if (v <= 0) return;
            const a1 = a0 + (v / total) * Math.PI * 2;
            ctx.beginPath();
            ctx.arc(cx, cy, r, a0 + .02, Math.max(a0 + .03, a1 - .02));
            ctx.strokeStyle = ENC_COLS[i];
            ctx.lineWidth = th;
            ctx.lineCap = 'butt';
            ctx.stroke();
            a0 = a1;
        });

        ctx.fillStyle = '#eaf2ff';
        ctx.font = '600 17px ui-monospace,monospace';
        ctx.textAlign = 'center';
        ctx.fillText(String(Math.round(total)), cx, cy - 4);
        ctx.font = FONT;
        ctx.fillStyle = INK + '.4)';
        ctx.fillText('AP', cx, cy + 11);
        ctx.textAlign = 'left';
        ctx.font = FONT;

        const lx = 106, step = Math.min(19, (h - 8) / ENC_CATS.length);
        let ly = cy - (ENC_CATS.length - 1) * step / 2;
        ENC_CATS.forEach((c, i) => {
            const v = dispEnc.get(c) || 0;
            ctx.fillStyle = ENC_COLS[i];
            ctx.beginPath();
            if (ctx.roundRect) ctx.roundRect(lx, ly - 3, 7, 7, 2); else ctx.rect(lx, ly - 3, 7, 7);
            ctx.fill();

            ctx.fillStyle = v > 0 ? INK + '.7)' : INK + '.25)';
            ctx.fillText(c, lx + 13, ly + .5);
            ctx.textAlign = 'right';
            ctx.fillStyle = v > 0 ? ACC : INK + '.22)';
            ctx.fillText(String(Math.round(v)), w - 6, ly + .5);
            ctx.textAlign = 'left';
            ly += step;
        });
    }

    /* ---- 厂商分布 ---- */
    function drawVend(){
        const { ctx, w, h } = fit(cv.vend);
        if (!apList.length) return empty(ctx, h, '暂无 AP');
        const all = new Map();
        for (const a of apList){
            const v = deviceOf(a.bssid, a.vendor).vendor;
            all.set(v, (all.get(v) || 0) + 1);
        }
        const top = [...all.entries()].sort((x, y) => y[1] - x[1]).slice(0, 6);
        const restN = [...all.values()].reduce((s, v) => s + v, 0) - top.reduce((s, e) => s + e[1], 0);
        const target = new Map(top);
        if (restN > 0) target.set('其他 ' + (all.size - top.length) + ' 家', restN);
        lerpMap(dispVend, target);

        const rows = [...target.keys()];
        const max = Math.max(1, ...[...target.values()]);
        const rowH = (h - 4) / rows.length;
        const labelW = Math.min(88, w * 0.3), barMax = w - labelW - 26;

        rows.forEach((name, i) => {
            const v = dispVend.get(name) || 0;
            const y = 2 + i * rowH + rowH / 2;
            ctx.fillStyle = INK + '.45)';
            ctx.fillText(name.length > 12 ? name.slice(0, 11) + '…' : name, 2, y);

            const bw = (v / max) * barMax;
            ctx.fillStyle = i === 0 ? ACC : INK + '.3)';
            const bh = Math.min(9, rowH - 5);
            ctx.beginPath();
            if (ctx.roundRect) ctx.roundRect(labelW, y - bh / 2, Math.max(1, bw), bh, 2);
            else ctx.rect(labelW, y - bh / 2, Math.max(1, bw), bh);
            ctx.fill();

            ctx.textAlign = 'right';
            ctx.fillStyle = INK + '.5)';
            ctx.fillText(String(Math.round(v)), w - 6, y);
            ctx.textAlign = 'left';
        });
    }

    /* ---- 发现节奏 ---- */
    const series = [];
    let tStart = 0;

    function drawTime(){
        const { ctx, w, h } = fit(cv.time);
        const tLast = series.length ? series[series.length - 1].t : 0;
        if (series.length < 2 || tLast < 1) return empty(ctx, h, '扫描中 · 每秒记一个点');

        const tMax = tLast;
        const nMax = Math.max(1, ...series.map(p => p.n));
        const xOf = t => 2 + (t / tMax) * (w - 6);
        const yOf = n => h - 13 - (n / nMax) * (h - 26);

        ctx.strokeStyle = INK + '.08)';
        ctx.beginPath(); ctx.moveTo(0, h - 12.5); ctx.lineTo(w, h - 12.5); ctx.stroke();

        ctx.beginPath();
        series.forEach((p, i) => i ? ctx.lineTo(xOf(p.t), yOf(p.n)) : ctx.moveTo(xOf(p.t), yOf(p.n)));
        ctx.lineTo(xOf(tMax), h - 12); ctx.lineTo(xOf(0), h - 12); ctx.closePath();
        ctx.fillStyle = INK + '.06)'; ctx.fill();

        ctx.beginPath();
        series.forEach((p, i) => i ? ctx.lineTo(xOf(p.t), yOf(p.n)) : ctx.moveTo(xOf(p.t), yOf(p.n)));
        ctx.strokeStyle = ACC;
        ctx.lineWidth = 1.4;
        ctx.lineJoin = 'round';
        ctx.stroke();

        const last = series[series.length - 1];
        ctx.beginPath();
        ctx.arc(xOf(last.t), yOf(last.n), 2, 0, Math.PI * 2);
        ctx.fillStyle = ACC; ctx.fill();

        ctx.fillStyle = INK + '.4)';
        ctx.fillText(last.n + ' 台', 2, 6);
        ctx.textAlign = 'right';
        ctx.fillText(tMax.toFixed(0) + 's', w - 6, h - 5);
        ctx.textAlign = 'left';
    }

    function drawAll(){
        drawChan(); drawRssi(); drawEnc(); drawVend(); drawTime();
    }

    /* 统计条独立刷, 1s 一次就够, 不必跟 60fps 重绘抢 DOM */
    function stats(){
        const n = apList.length;
        let open = 0, wpa3 = 0;
        const chs = new Map();
        for (const a of apList){
            const c = encCat(a.enc);
            if (c === '开放') open++;
            if (c === 'WPA3') wpa3++;
            if (a.channel) chs.set(a.channel, (chs.get(a.channel) || 0) + 1);
        }
        const P2 = (id, v) => { const el = P(id); if (el) el.textContent = String(v); };
        P2('chApN', n); P2('chOpenN', open); P2('chWpa3N', wpa3);
        let busy = '--';
        if (chs.size){
            const [ch, c] = [...chs.entries()].sort((x, y) => y[1] - x[1])[0];
            busy = 'ch' + ch;
        }
        P2('chBusy', busy);
        const hint = P('chHint');
        if (hint) hint.textContent = n
            ? '当前 ' + n + ' 台 · 开放 ' + open + ' 台 · ' + (open ? '无密码的可以直连' : '全部加密')
            : '图表跟随当前 AP 列表实时刷新。先扫一次。';
        const tn = P('chTimeNote');
        if (tn) tn.textContent = series.length < 2
            ? '每次重新扫描会从头计时。'
            : '峰值 ' + Math.max(...series.map(p => p.n)) + ' 台 · 用时 ' + series[series.length - 1].t.toFixed(0) + ' 秒';

    }

    setInterval(() => {
        const n = apList.length, now = Date.now();
        if (!n){ if (series.length){ series.length = 0; tStart = 0; } }
        else {
            /* 每秒一个点, 不变的也记: 只要"有变化才记", 两个点会落在同一秒,
             * 折线退化成竖线, 面积填充就成了一个假三角. */
            if (!tStart){ tStart = now - 1000; series.push({ t: 0, n: 0 }); }
            series.push({ t: (now - tStart) / 1000, n });
            if (series.length > 300) series.shift();
        }
        stats();
    }, 1000);

    let raf = 0;
    function loop(){
        if (!pan.classList.contains('active')){ raf = 0; return; }
        drawAll();
        raf = requestAnimationFrame(loop);
    }
    function start(){ if (!raf) raf = requestAnimationFrame(loop); }

    document.querySelector('.tab[data-tab="chart"]')?.addEventListener('click', () => setTimeout(start, 30));
    window.addEventListener('resize', () => { if (pan.classList.contains('active')) drawAll(); }, { passive: true });
    window.addEventListener('orientationchange', () => setTimeout(() => { if (pan.classList.contains('active')) drawAll(); }, 260), { passive: true });
})();
